    public function test_authority_isolation_and_view_only_matrix(): void
    {
        foreach (['president-admin', 'treasurer'] as $index => $role) { $f = $this->fixture3ijae('AUTH'.$index, $role); config(['instance.organisation_code' => $f['club']->code]); Sanctum::actingAs($f['actor']); $receipt = $this->postJson($this->receiptEndpoint3ijae($f), $this->receiptPayload3ijae($f))->assertCreated()->json('data.id'); $this->postJson($this->receiptEndpoint3ijae($f)."/{$receipt}/correction", $this->correctionPayload3ijae())->assertOk(); }
        $secretary = $this->fixture3ijae('SEC', 'secretary', ['finance.club.ordinary_income_receipts.view']); config(['instance.organisation_code' => $secretary['club']->code]); Sanctum::actingAs($secretary['actor']); $this->getJson($this->receiptEndpoint3ijae($secretary))->assertOk(); $this->postJson($this->receiptEndpoint3ijae($secretary).'/'.Str::uuid().'/correction', $this->correctionPayload3ijae())->assertForbidden();
        foreach (['member', 'arbitrary'] as $role) { $f = $this->fixture3ijae(strtoupper($role), $role, []); config(['instance.organisation_code' => $f['club']->code]); Sanctum::actingAs($f['actor']); $this->postJson($this->receiptEndpoint3ijae($f).'/'.Str::uuid().'/correction', $this->correctionPayload3ijae())->assertForbidden(); }
        $inactive = $this->fixture3ijae('INACTIVE'); DB::table('club_memberships')->where('club_id', $inactive['club']->id)->update(['status' => 'inactive']); config(['instance.organisation_code' => $inactive['club']->code]); Sanctum::actingAs($inactive['actor']); $this->postJson($this->receiptEndpoint3ijae($inactive).'/'.Str::uuid().'/correction', $this->correctionPayload3ijae())->assertForbidden();
        $foreign = $this->fixture3ijae('FOREIGN'); $owner = $this->fixture3ijae('OWNER'); config(['instance.organisation_code' => $owner['club']->code]); Sanctum::actingAs($owner['actor']); $id = $this->postJson($this->receiptEndpoint3ijae($owner), $this->receiptPayload3ijae($owner))->assertCreated()->json('data.id'); $journalCount = ClubJournalEntry::count(); $receiptCount = ClubOrdinaryIncomeReceipt::count(); $correctionCount = ClubOrdinaryIncomeReceiptCorrection::count(); config(['instance.organisation_code' => $foreign['club']->code]); Sanctum::actingAs($foreign['actor']); $this->postJson($this->receiptEndpoint3ijae($foreign)."/{$id}/correction", $this->correctionPayload3ijae())->assertNotFound()->assertJsonPath('message', 'Resource not found.'); $this->postJson($this->receiptEndpoint3ijae($foreign).'/'.Str::uuid().'/correction', $this->correctionPayload3ijae())->assertNotFound()->assertJsonPath('message', 'Resource not found.'); $this->assertSame($correctionCount, ClubOrdinaryIncomeReceiptCorrection::count()); $this->assertSame($journalCount, ClubJournalEntry::count()); $this->assertSame($receiptCount, ClubOrdinaryIncomeReceipt::count());
        config(['instance.organisation_code' => $owner['club']->code]); Sanctum::actingAs($owner['actor']); $this->postJson($this->receiptEndpoint3ijae($owner)."/{$id}/correction", $this->correctionPayload3ijae())->assertOk();
        $viewer = $this->fixture3ijae('VIEW', 'secretary', ['finance.club.ordinary_income_receipts.view']); DB::table('club_memberships')->where('user_id', $viewer['actor']->id)->update(['club_id' => $owner['club']->id]); config(['instance.organisation_code' => $owner['club']->code]); Sanctum::actingAs($viewer['actor']); $this->getJson($this->receiptEndpoint3ijae($owner)."/{$id}")->assertOk()->assertJsonPath('data.correction.reason', 'Incorrect amount');
    }

    public function test_reversal_is_exact_covered_immutable_and_idempotent(): void
    {
        $f = $this->fixture3ijae('REV'); config(['instance.organisation_code' => $f['club']->code]); Sanctum::actingAs($f['actor']); $id = $this->postJson($this->receiptEndpoint3ijae($f), $this->receiptPayload3ijae($f))->assertCreated()->json('data.id'); $source = ClubOrdinaryIncomeReceipt::firstOrFail(); $sourceFacts = $source->getAttributes(); $original = $source->journalEntry()->with('lines')->firstOrFail(); $lineFacts = $original->lines->map->getAttributes(); $payload = $this->correctionPayload3ijae();
        $first = $this->postJson($this->receiptEndpoint3ijae($f)."/{$id}/correction", $payload)->assertOk()->assertJsonPath('data.status', 'reversed'); $replay = $this->postJson($this->receiptEndpoint3ijae($f)."/{$id}/correction", $payload)->assertOk(); $this->assertSame($first->json('data.correction.id'), $replay->json('data.correction.id'));
        $reversal = ClubOrdinaryIncomeReceiptCorrection::firstOrFail()->reversalJournal()->with('lines')->firstOrFail(); $this->assertSame(['credit', 'debit'], $reversal->lines->pluck('direction')->all()); $this->assertSame([1, 2], $reversal->lines->pluck('line_number')->all()); $this->assertSame($original->lines->pluck('ledger_account_id')->all(), $reversal->lines->pluck('ledger_account_id')->all()); $this->assertSame($original->lines->pluck('amount_paise')->all(), $reversal->lines->pluck('amount_paise')->all()); $this->assertSame($sourceFacts, ClubOrdinaryIncomeReceipt::findOrFail($source->id)->getAttributes()); $this->assertEquals($lineFacts, $original->fresh()->lines->map->getAttributes());
        $this->postJson($this->receiptEndpoint3ijae($f)."/{$id}/correction", [...$payload, 'reason' => 'Changed'])->assertConflict()->assertJsonPath('code', 'ORDINARY_INCOME_RECEIPT_CORRECTION_CHANGED_RETRY'); $this->postJson($this->receiptEndpoint3ijae($f)."/{$id}/correction", [...$payload, 'idempotency_key' => (string) Str::uuid()])->assertConflict()->assertJsonPath('code', 'ORDINARY_INCOME_RECEIPT_ALREADY_CORRECTED');
        $this->postJson($this->receiptEndpoint3ijae($f)."/{$id}/correction", [...$payload, 'accounting_date' => '2027-08-13'])->assertConflict()->assertJsonPath('code', 'ORDINARY_INCOME_RECEIPT_CORRECTION_CHANGED_RETRY');
        try { ClubOrdinaryIncomeReceiptCorrection::firstOrFail()->update(['reason' => 'rewrite']); $this->fail('Correction update must fail.'); } catch (LogicException) { $this->addToAssertionCount(1); } try { ClubOrdinaryIncomeReceiptCorrection::firstOrFail()->delete(); $this->fail('Correction delete must fail.'); } catch (LogicException) { $this->addToAssertionCount(1); }
    }

    public function test_period_coverage_replacement_refund_and_atomic_rollback_contract(): void
    {
        $uncovered = $this->fixture3ijae('UNCOVERED', includePriorPeriod: true); config(['instance.organisation_code' => $uncovered['club']->code]); Sanctum::actingAs($uncovered['actor']); $uncoveredId = $this->postJson($this->receiptEndpoint3ijae($uncovered), $this->receiptPayload3ijae($uncovered))->assertCreated()->json('data.id'); $this->assertSame('open', $uncovered['priorPeriod']->status); $this->postJson($this->receiptEndpoint3ijae($uncovered)."/{$uncoveredId}/correction", [...$this->correctionPayload3ijae(), 'accounting_date' => '2027-06-30'])->assertUnprocessable()->assertJsonPath('code', 'ORDINARY_INCOME_RECEIPT_CORRECTION_COVERAGE_MISSING'); $uncoveredOriginal = ClubOrdinaryIncomeReceipt::where('club_id', $uncovered['club']->id)->where('public_id', $uncoveredId)->firstOrFail(); $this->assertSame(1, ClubOrdinaryIncomeReceipt::where('club_id', $uncovered['club']->id)->count()); $this->assertFalse($uncoveredOriginal->correction()->exists()); $this->assertFalse($uncoveredOriginal->correctedReplacement()->exists()); $this->assertSame($uncovered['club']->id, $uncoveredOriginal->journalEntry->club_id); $this->assertSame('club_ordinary_income_receipt', $uncoveredOriginal->journalEntry->source_type); $this->assertSame($uncoveredId, $uncoveredOriginal->journalEntry->source_id);
        $f = $this->fixture3ijae('SAFE'); config(['instance.organisation_code' => $f['club']->code]); Sanctum::actingAs($f['actor']); $id = $this->postJson($this->receiptEndpoint3ijae($f), $this->receiptPayload3ijae($f))->assertCreated()->json('data.id'); $safeOriginal = ClubOrdinaryIncomeReceipt::where('club_id', $f['club']->id)->where('public_id', $id)->firstOrFail();
        DB::table('club_accounting_periods')->where('id', $f['period']->id)->update(['status' => 'closed', 'closed_at' => now(), 'closed_by_user_id' => $f['actor']->id]); $this->postJson($this->receiptEndpoint3ijae($f)."/{$id}/correction", $this->correctionPayload3ijae())->assertUnprocessable()->assertJsonPath('code', 'ORDINARY_INCOME_RECEIPT_CORRECTION_PERIOD_INVALID'); DB::table('club_accounting_periods')->where('id', $f['period']->id)->update(['status' => 'open', 'closed_at' => null, 'closed_by_user_id' => null]);
        $replacement = $this->receiptPayload3ijae($f); unset($replacement['idempotency_key']); $this->postJson($this->receiptEndpoint3ijae($f)."/{$id}/correction", [...$this->correctionPayload3ijae(replacement: $replacement), 'replacement' => [...$replacement, 'refund_method' => 'cash']])->assertUnprocessable()->assertJsonValidationErrors('replacement.refund_method'); $bad = [...$replacement, 'subtype' => 'donation']; $this->postJson($this->receiptEndpoint3ijae($f)."/{$id}/correction", $this->correctionPayload3ijae(replacement: $bad))->assertUnprocessable(); $this->assertFalse($safeOriginal->correction()->exists()); $this->assertSame(ClubJournalEntry::STATUS_POSTED, $safeOriginal->journalEntry->status);
        $this->postJson($this->receiptEndpoint3ijae($f)."/{$id}/correction", $this->correctionPayload3ijae(replacement: $replacement))->assertOk()->assertJsonPath('data.status', 'replaced'); $safeCorrection = ClubOrdinaryIncomeReceiptCorrection::where('club_id', $f['club']->id)->where('original_receipt_id', $safeOriginal->id)->firstOrFail(); $safeReplacement = $safeCorrection->replacementReceipt()->with('journalEntry')->firstOrFail(); $this->assertSame(2, ClubOrdinaryIncomeReceipt::where('club_id', $f['club']->id)->count()); $this->assertSame(1, ClubOrdinaryIncomeReceipt::where('club_id', $uncovered['club']->id)->count()); $this->assertSame($safeOriginal->id, $safeCorrection->original_receipt_id); $this->assertSame($safeOriginal->journal_entry_id, $safeCorrection->original_journal_entry_id); $this->assertSame($f['club']->id, $safeReplacement->club_id); $this->assertNotSame($id, $safeReplacement->public_id); $this->assertSame($safeOriginal->id, $safeReplacement->corrected_from_receipt_id); $this->assertSame($safeReplacement->id, $safeCorrection->replacement_receipt_id); $this->assertSame($f['club']->id, $safeReplacement->journalEntry->club_id); $this->assertSame('club_ordinary_income_receipt', $safeReplacement->journalEntry->source_type); $this->assertSame($safeReplacement->public_id, $safeReplacement->journalEntry->source_id); $this->assertNotSame($uncoveredOriginal->id, $safeCorrection->original_receipt_id); $this->assertNotSame($uncovered['club']->id, $safeCorrection->club_id); $this->assertFalse($uncoveredOriginal->fresh()->correctedReplacement()->exists());
    }

    public function test_closed_original_period_remains_closed_while_later_covered_period_accepts_correction(): void
