    public function test_request_boundaries_and_cross_source_idempotency_are_stable(): void
    {
        $f = $this->fixture3ijae('BOUNDARY'); config(['instance.organisation_code' => $f['club']->code]); Sanctum::actingAs($f['actor']); $receiptPayload = $this->receiptPayload3ijae($f); $id = $this->postJson($this->receiptEndpoint3ijae($f), $receiptPayload)->assertCreated()->json('data.id'); $endpoint = $this->receiptEndpoint3ijae($f)."/{$id}/correction";
        $this->postJson($endpoint, [...$this->correctionPayload3ijae(), 'reason' => '   '])->assertUnprocessable();
        $this->postJson($endpoint, [...$this->correctionPayload3ijae(), 'reason' => str_repeat('x', 1001)])->assertUnprocessable();
        $this->postJson($endpoint, [...$this->correctionPayload3ijae(), 'amount_paise' => 1])->assertUnprocessable()->assertJsonValidationErrors('amount_paise');
        foreach ([[], null, [['direction' => 'debit']], 'caller-owned', (object) ['direction' => 'debit']] as $journalLines) $this->postJson($endpoint, [...$this->correctionPayload3ijae(), 'journal_lines' => $journalLines])->assertUnprocessable()->assertJsonValidationErrors('journal_lines');
        foreach (['amount_paise', 'fund', 'journal_entry_id', 'reversal_journal_entry_id', 'replacement_receipt_id', 'currency', 'status'] as $field) $this->postJson($endpoint, [...$this->correctionPayload3ijae(), $field => null])->assertUnprocessable()->assertJsonValidationErrors($field);
        foreach (['refund', 'refund_amount', 'refund_method', 'refund_account', 'payment_out', 'payment_method', 'payment_reference', 'payout', 'returned_cash'] as $field) $this->postJson($endpoint, [...$this->correctionPayload3ijae(), $field => 'forbidden'])->assertUnprocessable()->assertJsonValidationErrors($field);
        $replacement = $this->receiptPayload3ijae($f); unset($replacement['idempotency_key']); foreach ([null, [], ['line' => 'forbidden']] as $nestedLines) $this->postJson($endpoint, [...$this->correctionPayload3ijae(replacement: $replacement), 'replacement' => [...$replacement, 'journal_lines' => $nestedLines]])->assertUnprocessable()->assertJsonValidationErrors('replacement.journal_lines');
        $this->postJson($endpoint, $this->correctionPayload3ijae($receiptPayload['idempotency_key']))->assertUnprocessable()->assertJsonPath('code', 'ORDINARY_INCOME_RECEIPT_CORRECTION_POSTING_FAILED');
        $this->assertDatabaseCount('club_ordinary_income_receipt_corrections', 0);
    }

