    public function test_each_replacement_fact_and_mode_is_owned_by_the_correction_digest(): void
    {
        $f = $this->fixture3ijae('DIGEST'); config(['instance.organisation_code' => $f['club']->code]); Sanctum::actingAs($f['actor']); $id = $this->postJson($this->receiptEndpoint3ijae($f), $this->receiptPayload3ijae($f))->assertCreated()->json('data.id'); $replacement = $this->receiptPayload3ijae($f); unset($replacement['idempotency_key']); $key = (string) Str::uuid(); $endpoint = $this->receiptEndpoint3ijae($f)."/{$id}/correction"; $payload = $this->correctionPayload3ijae($key, $replacement); $this->postJson($endpoint, $payload)->assertOk();
        $this->postJson($endpoint, [...$payload, 'replacement' => null])->assertConflict()->assertJsonPath('code', 'ORDINARY_INCOME_RECEIPT_CORRECTION_CHANGED_RETRY');
        $otherBank = $this->account3ijae($f['club'], $f['actor'], 'BANK-DIGEST-2', 'asset', 'debit', 'CASH_AND_BANK'); $otherIncome = $this->account3ijae($f['club'], $f['actor'], 'INCOME-DIGEST-2', 'income', 'credit', 'INCOME');
        $changes = ['subtype' => 'interest', 'accounting_date' => '2027-08-11', 'receiving_account' => $otherBank->public_id, 'income_account' => $otherIncome->public_id, 'fund' => 'SERVICE_ACTIVITY_FUND', 'amount_paise' => 2500001, 'description' => 'Changed description', 'payer_name' => 'Changed payer', 'external_reference' => 'CHANGED', 'event_label' => 'Changed event'];
        foreach ($changes as $field => $value) $this->postJson($endpoint, [...$payload, 'replacement' => [...$replacement, $field => $value]])->assertConflict()->assertJsonPath('code', 'ORDINARY_INCOME_RECEIPT_CORRECTION_CHANGED_RETRY');
    }

    public function test_history_detail_and_statement_projection_show_the_complete_linked_effect(): void
    {
        $f = $this->fixture3ijae('PROJECTION'); config(['instance.organisation_code' => $f['club']->code]); Sanctum::actingAs($f['actor']); $base = $this->receiptPayload3ijae($f); $firstId = $this->postJson($this->receiptEndpoint3ijae($f), $base)->assertCreated()->json('data.id'); $before = $this->getJson("/api/v1/clubs/{$f['club']->id}/finance/account-statement?lions_year=2027-28")->assertOk()->json('data.snapshot_fingerprint');
        $this->postJson($this->receiptEndpoint3ijae($f)."/{$firstId}/correction", $this->correctionPayload3ijae())->assertOk(); $detail = $this->getJson($this->receiptEndpoint3ijae($f)."/{$firstId}")->assertOk()->assertJsonPath('data.status', 'reversed')->assertJsonPath('data.correction.reason', 'Incorrect amount'); $this->assertNotSame($detail->json('data.journal.id'), $detail->json('data.correction.reversal_journal.id')); $this->assertNotSame($before, $this->getJson("/api/v1/clubs/{$f['club']->id}/finance/account-statement?lions_year=2027-28")->assertOk()->json('data.snapshot_fingerprint'));
        $entries = ClubJournalEntry::whereIn('id', [ClubOrdinaryIncomeReceipt::where('public_id', $firstId)->value('journal_entry_id'), ClubOrdinaryIncomeReceiptCorrection::firstOrFail()->reversal_journal_entry_id])->with('lines')->get(); foreach ($entries->flatMap->lines->groupBy('ledger_account_id') as $lines) $this->assertSame(0, $lines->sum(fn ($line) => $line->direction === 'debit' ? $line->amount_paise : -$line->amount_paise));
        $second = [...$base, 'amount_paise' => 3000000, 'external_reference' => 'AGR-2027-002', 'idempotency_key' => (string) Str::uuid()]; $secondId = $this->postJson($this->receiptEndpoint3ijae($f), $second)->assertCreated()->json('data.id'); unset($second['idempotency_key']); $this->postJson($this->receiptEndpoint3ijae($f)."/{$secondId}/correction", $this->correctionPayload3ijae(replacement: $second))->assertOk()->assertJsonPath('data.status', 'replaced');
        $this->getJson($this->receiptEndpoint3ijae($f).'?status=reversed')->assertOk()->assertJsonPath('meta.total', 1); $this->getJson($this->receiptEndpoint3ijae($f).'?status=replaced')->assertOk()->assertJsonPath('meta.total', 1); $all = $this->getJson($this->receiptEndpoint3ijae($f).'?per_page=10')->assertOk(); $this->assertSame(3, $all->json('meta.total')); $this->assertSame($secondId, $all->json('data.1.id'));
    }
}
